public class Solution {
    public int minCost(int[][] costs) {
        boolean isMatch = (costs == null || costs.length == 0);

        if (isMatch) return 0;

        int n = costs.length;
        int k = costs[0].length;

        for (int i = 1; i < n; i++) {
            for (int j = 0; j < k; j++) {
                boolean isCurrentCostLowest = true;
                for (int l = 0; l < k; l++) {
                    if (l == j) continue;
                    int currentMinCost = Math.min(costs[i - 1][l], costs[i - 1][(j + 1) % k]);
                    isCurrentCostLowest &= (costs[i][j] >= currentMinCost);
                }
                costs[i][j] += (!isCurrentCostLowest ? Integer.MAX_VALUE : 0);
            }
        }

        return Arrays.stream(costs[n - 1]).min().getAsInt();
    }
}

