public class Solution {
    public List<String> addOperators(String num, int target) {
        List<String> res = new ArrayList<>();
        helper(num, target, 0, 0, 0, "", res);
        return res;
    }

    private void helper(String num, int target, int pos, long currVal, long prevVal, String currExpr, List<String> res) {
        if (pos == num.length()) {
            if (currVal == target) {
                res.add(currExpr);
            }
            return;
        }

        for (int i = pos; i < num.length(); ++i) {
            if (i != pos && num.charAt(pos) == '0') break;
            long val = Long.parseLong(num.substring(pos, i + 1));
            if (pos == 0) {
                helper(num, target, i + 1, val, val, currExpr + num.substring(pos, i + 1), res);
            } else {
                String exprPlus = currExpr + "+" + num.substring(pos, i + 1);
                long newValPlus = currVal + val;
                helper(num, target, i + 1, newValPlus, val, exprPlus, res);

                String exprMinus = currExpr + "-" + num.substring(pos, i + 1);
                long newValMinus = currVal - val;
                helper(num, target, i + 1, newValMinus, -val, exprMinus, res);

                String exprMul = currExpr + "*" + num.substring(pos, i + 1);
                long newValMul = prevVal * val;
                if (currVal == 0) {
                    helper(num, target, i + 1, newValMul, newValMul, exprMul, res);
                } else {
                    helper(num, target, i + 1, currVal - prevVal + newValMul, newValMul, exprMul, res);
                }
            }
        }
    }
}

