        int[][] dist_sum = new int[m][n];
        int house_count = 0;

        int[][] dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 1) {
                    house_count++;
                    Queue<int[]> q = new LinkedList<>();
                    q.offer(new int[]{i, j});
                    boolean[][] visited = new boolean[m][n];
                    int level = 1;
                    while (!q.isEmpty()) {
                        int sz = q.size();
                        for (int q_i = 0; q_i < sz; q_i++) {
                            int[] cur = q.poll();
                            int x = cur[0];
                            int y = cur[1];
                            for (int[] dir : dirs) {
                                int x_new = x + dir[0];
                                int y_new = y + dir[1];
                                if (x_new >= 0 && x_new < m && y_new >= 0 && y_new < n && !visited[x_new][y_new] && grid[x_new][y_new] == 0) {
