        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                if (total_count[i][j] > 1 && total_count[x][y] == 1) {
                    dist_sum[i][j] += dist_sum[x][y];
                    total_count[i][j]++;
                }
            }
        }

