public class Solution {
    public int coinChange(int[] coins, int amount) {
        return splitCoinChange(coins, amount);
    }

    private int splitCoinChange(int[] coins, int amount) {
        int[] dp = new int[amount + 1];
        Arrays.fill(dp, amount + 1);
        dp[0] = 0;

        for (int coin : coins) {
            updateDPForCoins(coins, amount, dp);
        }

        return dp[amount] <= amount ? dp[amount] : -1;
    }

    private void updateDPForCoins(int[] coins, int amount, int[] dp) {
        for (int i = 0; i < coins.length && coin * i <= amount; i++) {
            for (int j = coin * i; j <= amount; j++) {
                dp[j] = Math.min(dp[j], dp[j - coin * i] + i);
            }
        }
    }
}

