        for(int i = 0; i < strs.size(); ++i) {
            boolean isUncommon = true;
            for(int j = 0; j < strs.size(); ++j) {
                if(i != j && strs.get(j).contains(strs.get(i))) {
                    isUncommon = false;
                    break;
                }
            }
            if(isUncommon) {
                maxLength = Math.max(maxLength, strs.get(i).length());
            }
        }
        return maxLength;
    }
}

